CREATE TABLE "administrative_enheter"."typeavgrensning" (
  "identifier" text PRIMARY KEY,
  "description" text
);

Merknad:
Avtalt avgrensningslinje vil normalt gjelde alle aktuelle former for kyststatsjurisdiksjon. Detaljene vil framgå av den aktuelle avgrensningsavtale.

Merknad 2:
Benyttes også som avgrensning av kontinentalsokkel i internasjonalt farvann, der flere stater kan framlegge dokumentasjon om rettigheter til sokkelen, men der statene har kommet til enighet om en avgrensningslinje.'),
  ('Kommunegrense', 'avgrensing av kommune'),
  ('Fylkesgrense', 'avgrensning av fylke'),
  ('Grunnkretsgrense', 'avgrensning av grunnkrets'),
  ('Delområdegrense', 'avgrensning av delområde'),
  ('Stemmekretsgrense', 'avgrensing av Stemmekrets');

CREATE TABLE "administrative_enheter"."fylkesnummer" (
  "identifier" text PRIMARY KEY,
  "description" text
);

CREATE TABLE "administrative_enheter"."spraakkode" (
  "identifier" text PRIMARY KEY,
  "description" text
);

CREATE TABLE "administrative_enheter"."kommune" (
  "objid" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "objtype" text NOT NULL DEFAULT 'Kommune',
  "identifikasjon_lokalid" text NOT NULL,
  "identifikasjon_navnerom" text NOT NULL,
  "identifikasjon_versjonid" text,
  "oppdateringsdato" timestamp with time zone NOT NULL,
  "gyldigfra" date,
  "gyldigtil" date,
  "datafangstdato" timestamp with time zone,
  "datauttaksdato" timestamp with time zone,
  "opphav" text,
  "omraade" geometry(MultiPolygon, 25833) NOT NULL,
  "kommunenummer" text NOT NULL,
  "kommunenavn" text NOT NULL,
  "samiskforvaltningsomraade" boolean
);

CREATE TABLE "administrative_enheter"."grense" (
  "objid" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "objtype" text NOT NULL DEFAULT 'Grense',
  "identifikasjon_lokalid" text NOT NULL,
  "identifikasjon_navnerom" text NOT NULL,
  "identifikasjon_versjonid" text,
  "oppdateringsdato" timestamp with time zone NOT NULL,
  "gyldigfra" date,
  "gyldigtil" date,
  "datafangstdato" timestamp with time zone,
  "kvalitet_maalemetode" text,
  "kvalitet_noeyaktighet" integer,
  "datauttaksdato" timestamp with time zone,
  "opphav" text,
  "grense" geometry(LineString, 25833) NOT NULL,
  "avgrensningstype" text NOT NULL
